import{_ as e,o as t,c as o,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"UncivCN 新特性","description":"","frontmatter":{"title":"UncivCN 新特性"},"headers":[],"relativePath":"zh/UncivCN/Features.md","filePath":"zh/UncivCN/Features.md"}'),r={name:"zh/UncivCN/Features.md"};function n(l,a,c,s,d,h){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="uncivcn-新特性" tabindex="-1">UncivCN 新特性 <a class="header-anchor" href="#uncivcn-新特性" aria-label="Permalink to &quot;UncivCN 新特性&quot;">​</a></h1><p>本文逐项介绍 UncivCN 分支相对上游新增的功能。括号内为引入版本。</p><h2 id="lua-模组系统-4-20-8-2-起-持续增强" tabindex="-1">Lua 模组系统（4.20.8.2 起，持续增强） <a class="header-anchor" href="#lua-模组系统-4-20-8-2-起-持续增强" aria-label="Permalink to &quot;Lua 模组系统（4.20.8.2 起，持续增强）&quot;">​</a></h2><p>模组可以挂载 Lua 脚本，实现远超纯 JSON 的复杂逻辑：</p><ul><li><strong>触发方式</strong>：通过 Unique 语法触发（如 <code>LuaEvent</code>），或挂载游戏生命周期钩子</li><li><strong>ctx 上下文对象</strong>：脚本内可访问 <code>civ</code>（文明）、<code>city</code>（城市）、<code>unit</code>（单位）、<code>tile</code>（地块）、<code>game</code>（全局）等 API</li><li><strong>工具链</strong>：原生模组检查器可筛查模组的 Lua 错误（4.20.8.4）；<code>game.findTiles</code> 等便捷 API（4.20.8.2 后）</li></ul><p>完整教程见 <a href="/Unciv/zh/Modders/Lua-Modding.html">Lua 脚本</a>。</p><h2 id="镜像与环形地图-4-20-7-3-4-20-7-4-4-21-0-起" tabindex="-1">镜像与环形地图（4.20.7.3 / 4.20.7.4 / 4.21.0 起） <a class="header-anchor" href="#镜像与环形地图-4-20-7-3-4-20-7-4-4-21-0-起" aria-label="Permalink to &quot;镜像与环形地图（4.20.7.3 / 4.20.7.4 / 4.21.0 起）&quot;">​</a></h2><ul><li><strong>三种镜像地图模式</strong>：创建游戏时可选，镜像模式下资源也对称分布（4.20.7.4）</li><li><strong>环形地图</strong>：地图首尾相接，取消旋转对称地图对半径的奇偶限制（4.20.17.2）</li></ul><h2 id="单位钉-地图钉-4-20-17-2" tabindex="-1">单位钉 / 地图钉（4.20.17.2） <a class="header-anchor" href="#单位钉-地图钉-4-20-17-2" aria-label="Permalink to &quot;单位钉 / 地图钉（4.20.17.2）&quot;">​</a></h2><p>在世界屏幕右下角小地图左侧新增两个独立开关：</p><ul><li><strong>单位钉</strong>：开启后可点击任意单位（含他国单位）添加备注，备注显示在单位兵棋正下方；再次点击可编辑或删除；同一地块多单位时弹出选择列表</li><li><strong>地图钉</strong>：可点击任意地块（含无单位地块）添加备注，显示在地块上，优先级高于食物/产能/金币等产出图标</li></ul><p>备注数据保存在 <code>{存档名}_notes</code> 文件中。</p><h2 id="地块归属-tile-claim-4-21-0-合并上游前自研-持续维护" tabindex="-1">地块归属 tile-claim（4.21.0 合并上游前自研，持续维护） <a class="header-anchor" href="#地块归属-tile-claim-4-21-0-合并上游前自研-持续维护" aria-label="Permalink to &quot;地块归属 tile-claim（4.21.0 合并上游前自研，持续维护）&quot;">​</a></h2><p>城市可对周边地块宣称归属（Claim）并交换地块，相关功能随上游演进持续适配。</p><h2 id="人口自动锁定按钮-4-21-0-1" tabindex="-1">人口自动锁定按钮（4.21.0.1） <a class="header-anchor" href="#人口自动锁定按钮-4-21-0-1" aria-label="Permalink to &quot;人口自动锁定按钮（4.21.0.1）&quot;">​</a></h2><p>城市屏幕右下角新增 <strong>自动锁定</strong> 按钮，可<strong>永久切换</strong>「不锁人口 / 锁人口」两种工作地块分配策略，替代原版每次手动锁定的快捷方式。</p><h2 id="随机数读档可变性-4-21-0-1" tabindex="-1">随机数读档可变性（4.21.0.1） <a class="header-anchor" href="#随机数读档可变性-4-21-0-1" aria-label="Permalink to &quot;随机数读档可变性（4.21.0.1）&quot;">​</a></h2><p>单机模式下读档后随机数序列可变（不再固定），4.21.0.1 起该功能<strong>联机时不可用</strong>，保证多人对局公平性。</p><h2 id="新建游戏设置导出-导入剪贴板-4-21-5-1" tabindex="-1">新建游戏设置导出 / 导入剪贴板（4.21.5.1） <a class="header-anchor" href="#新建游戏设置导出-导入剪贴板-4-21-5-1" aria-label="Permalink to &quot;新建游戏设置导出 / 导入剪贴板（4.21.5.1）&quot;">​</a></h2><p>新建游戏时可将当前全部设置复制到剪贴板，或从剪贴板粘贴恢复，方便分享开局配置。</p><h2 id="轮询联机-4-20-8-1" tabindex="-1">轮询联机（4.20.8.1） <a class="header-anchor" href="#轮询联机-4-20-8-1" aria-label="Permalink to &quot;轮询联机（4.20.8.1）&quot;">​</a></h2><p>在动态回合基础上新增<strong>轮询联机</strong>模式：同一回合拆分为固定时长的时间片，玩家间按时间片轮流传递存档，将等待上限从「对手想多久就多久」压缩为数秒。</p><ul><li>创建游戏时勾选 Online Multiplayer 后可选 Polling interval（Off / 5s / 10s / 15s / 20s / 30s）</li><li>可查看其他玩家的在线状态（4.20.8.4）</li></ul><p>完整机制见 [轮询联机机制./Polling-multiplayer)。</p><h2 id="默认服务器-4-21-0-1" tabindex="-1">默认服务器（4.21.0.1） <a class="header-anchor" href="#默认服务器-4-21-0-1" aria-label="Permalink to &quot;默认服务器（4.21.0.1）&quot;">​</a></h2><p>联机默认服务器改为 <code>http://sp.unciv.cn:30123</code>。</p><h2 id="游戏版本兼容性隔离-4-20-17-2" tabindex="-1">游戏版本兼容性隔离（4.20.17.2） <a class="header-anchor" href="#游戏版本兼容性隔离-4-20-17-2" aria-label="Permalink to &quot;游戏版本兼容性隔离（4.20.17.2）&quot;">​</a></h2><p>旧版客户端无法加载新版存档，避免版本混用导致的存档损坏。</p><h2 id="mergeaction-扩展-json-系统-4-20-7-3" tabindex="-1">MergeAction 扩展 JSON 系统（4.20.7.3） <a class="header-anchor" href="#mergeaction-扩展-json-系统-4-20-7-3" aria-label="Permalink to &quot;MergeAction 扩展 JSON 系统（4.20.7.3）&quot;">​</a></h2><p>在原版基础上扩展 <code>_mergeAction</code>（字段级合并）能力，模组可增量修改规则集对象而不必整对象替换。 另有多个新增 Countables 参数类型、Amount 参数兼容 Countables（4.20.8.2）。</p><p>教程见 <a href="/Unciv/zh/Modders/Mod-file-structure/6-MergeActions.html">UncivCN 扩展 JSON - MergeAction 教程</a>。</p><h2 id="历史-自带-uccc-模组-4-21-0-1-→-4-21-5-1-撤销" tabindex="-1">历史：自带 UCCC 模组（4.21.0.1 → 4.21.5.1 撤销） <a class="header-anchor" href="#历史-自带-uccc-模组-4-21-0-1-→-4-21-5-1-撤销" aria-label="Permalink to &quot;历史：自带 UCCC 模组（4.21.0.1 → 4.21.5.1 撤销）&quot;">​</a></h2><p>4.21.0.1 曾随游戏本体打包 UCCC 模组；4.21.5.1 起撤销该改动，游戏本体不再打包任何模组，模组需另行下载。</p>',33)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
